// === Tab: mySketch ===
ArrayList<Circle> circles = new ArrayList<Circle>();
let c;
function setup() {
	createCanvas(1112, 834);
	colorMode(HSB, 255);
}

function draw() {
	background(0); 
	for (i = 0; i < circles.size(); ++i) {
		for (k = 0; k < circles.size(); ++k) {
			if (i!=k) {
				let f = circles.get(k).attract(circles.get(i));
				circles.get(i).applyForce(f);
				circles.get(i).link(circles.get(k));
			}
		} 
		circles.get(i).update();
		circles.get(i).display();
		circles.get(i).checkEdges();
	}
}

function mouseClicked(){
	c = new Circle();
	circles.add(c);
}

function mouseDragged(){
	c = new Circle();
	circles.add(c);
}

class Circle{
	location,velocity,acceleration;
	G,mass,size;

	constructor(){
		location = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		velocity = new PVector(0,0);
		acceleration = new PVector(0,0);
		G = 0.6;
		mass = random(2,5);
		size = mass;
	}

	function applyForce(force){
		var f = force.get();
		f.div(mass);
		acceleration.add(f);
	}

	function update(){
		velocity.add(acceleration);
		location.add(velocity);
		acceleration.mult(0);
	}

	function display(){
		noStroke();
		//fill(255);
		ellipse(location.x, location.y,size,size);
	}

	function link(c){
		stroke(location.y%255, 255, 255, 75);
		let dist = PVector.sub(c.location,location);
		if (dist.mag()<500) {
			line(location.x, location.y, c.location.x, c.location.y);
		}
	}

	attract(c){
		let force = PVector.sub(location,c.location);
		let distance = force.mag();
		distance = constrain(distance, 20, 25);
		force.normalize();
		let strength = (G*mass*c.mass)/(distance*distance);
		force.mult(strength);
		return force;
	}

	function checkEdges(){
		if (location.x < size/2) {
			location.x = size/2;
			velocity.x *= -1;
		} else if (location.x > width-size/2){
			location.x = width-size/2;
			velocity.x *= -1;
		}

		if (location.y < size/2) {
			location.y = size/2;
			velocity.y *= -1;
		} else if (location.y > height-size/2){
			location.y = height-size/2;
			velocity.y *= -1;
		}
	}
}

